      @if (regionCounts().length === 0) {
        <p>No regions yet.</p>
      } @else {
        <ul>
          @for (r of regionCounts(); track r.region) {
            <li>
              {{ r.region }}: <strong [attr.data-testid]="'region-count-' + r.region">{{ r.count }}</strong>
            </li>
          }
        </ul>
